    10→const mockFetch = vi.fn();
    11→vi.stubGlobal("fetch", mockFetch);
    12→
    13→const TEST_CREDENTIALS = { api_key: "test-key", secret: "test-secret", passphrase: "test-pass" };
    14→
    15→describe("testConnection", () => {
    16→  beforeEach(() => {
    17→    mockFetch.mockReset();
    18→  });
    19→
    20→  // ─── OKX ─────────────────────────────────────────────────────────────────────
    21→
    22→  describe("okxExchange", () => {
    23→    it("returns success when code is '0'", async () => {
    24→      mockFetch.mockResolvedValue({
    25→        ok: true,
    26→        json: async () => ({ code: "0", msg: "" }),
    27→      });
    28→      const result = await okxExchange.testConnection(TEST_CREDENTIALS);
    29→      expect(result.success).toBe(true);
    30→      expect(result.latency_ms).toBeDefined();
    31→      expect(mockFetch).toHaveBeenCalledOnce();
    32→      const [url, opts] = mockFetch.mock.calls[0];
    33→      expect(url).toContain("/api/v5/account/balance");
    34→      expect(opts.signal).toBeDefined();
    35→    });
    36→
    37→    it("returns failure with error message when code is non-zero", async () => {
    38→      mockFetch.mockResolvedValue({
    39→        ok: false,
    40→        json: async () => ({ code: "50111", msg: "Invalid API key" }),
    41→      });
    42→      const result = await okxExchange.testConnection(TEST_CREDENTIALS);
    43→      expect(result.success).toBe(false);
    44→      expect(result.error).toBe("Invalid API key");
    45→      expect(result.latency_ms).toBeDefined();
    46→    });
    47→
    48→    it("returns failure with fallback message when msg is undefined", async () => {
    49→      mockFetch.mockResolvedValue({
    50→        ok: false,
    51→        json: async () => ({ code: "50000" }),
    52→      });
    53→      const result = await okxExchange.testConnection(TEST_CREDENTIALS);
    54→      expect(result.success).toBe(false);
    55→      expect(result.error).toBe("Error code: 50000");
    56→    });
    57→
    58→    it("handles network error", async () => {
    59→      mockFetch.mockRejectedValue(new Error("Network timeout"));
    60→      const result = await okxExchange.testConnection(TEST_CREDENTIALS);
    61→      expect(result.success).toBe(false);
    62→      expect(result.error).toBe("Network timeout");
    63→      expect(result.latency_ms).toBeDefined();
    64→    });
    65→  });
