    11→  referral_url: "https://accounts.binance.com/register?ref=11427183",
    12→  api_doc_url: "https://www.binance.com/en/my/settings/api-management",
    13→  whitelist_ip: "195.135.193.235",
    14→
    15→  sign(credentials: Credentials, params: SignParams): SignedRequest {
    16→    const { method, path } = params;
    17→    const queryString = params.params
    18→      ? Object.entries(params.params).map(([k, v]) => `${k}=${v}`).join("&")
    19→      : "";
    20→    const toSign = queryString + (queryString ? "&" : "") + `timestamp=${params.timestamp}`;
    21→    const signature = createHmac("sha256", credentials.secret)
    22→      .update(toSign)
    23→      .digest("hex");
    24→    const fullQuery = toSign + `&signature=${signature}`;
    25→
    26→    return {
    27→      url: `${BASE_URL}${path}?${fullQuery}`,
    28→      headers: {
    29→        "X-MBX-APIKEY": credentials.api_key,
    30→      },
    31→    };
    32→  },
