    34→  async testConnection(credentials: Credentials): Promise<TestResult> {
    35→    const timestamp = Date.now().toString();
    36→    const path = "/api/v3/account";
    37→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
    38→
    39→    const start = Date.now();
