    41→      const res = await fetch(signed.url, {
    42→        method: "GET",
    43→        headers: signed.headers,
    44→        signal: AbortSignal.timeout(10_000),
    45→      });
    46→      const latency_ms = Date.now() - start;
    47→
    48→      if (res.ok) return { success: true, latency_ms };
    49→      const json = (await res.json()) as { msg?: string; code?: number };
